export function truncate(text: string, maxLen: number): string {
  if (typeof text !== 'string') {
    throw new TypeError('truncate expects a string text argument');
  }
  if (typeof maxLen !== 'number' || !Number.isFinite(maxLen) || maxLen < 0) {
    throw new TypeError('truncate expects a non-negative finite number maxLen');
  }

  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen).trim() + '...';
}

export function titleCase(str: string): string {
  if (typeof str !== 'string') {
    throw new TypeError('titleCase expects a string argument');
  }

  return str
    .toLowerCase()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export function stripHtml(html: string): string {
  if (typeof html !== 'string') {
    throw new TypeError('stripHtml expects a string argument');
  }

  return html.replace(/<[^>]+>/g, '');
}

export function slugify(str: string): string {
  if (typeof str !== 'string') {
    throw new TypeError('slugify expects a string argument');
  }

  return str
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
}

export function escapeRegex(str: string): string {
  if (typeof str !== 'string') {
    throw new TypeError('escapeRegex expects a string argument');
  }

  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import pino, { type Logger, type LoggerOptions } from 'pino';

export interface RequestContext {
  requestId?: string;
  correlationId?: string;
  method?: string;
  url?: string;
  userId?: string;
  ip?: string;
}

export interface LoggerConfig {
  serviceName?: string;
  level?: string;
  logDir?: string;
  maxSize?: string;
  maxFiles?: number;
}

export function createRequestContext(req: Partial<RequestContext> = {}): RequestContext {
  return {
    requestId: req.requestId ?? crypto.randomUUID(),
    correlationId: req.correlationId ?? crypto.randomUUID(),
    method: req.method,
    url: req.url,
    userId: req.userId,
    ip: req.ip,
  };
}

function createRotatingDestination(logDir: string, serviceName: string, maxSize: string, maxFiles: number) {
  fs.mkdirSync(logDir, { recursive: true });
  const filePath = path.join(logDir, `${serviceName}.log`);
  return pino.destination({ dest: filePath, sync: false, minLength: 4096, append: true });
}

export function createChildLogger(baseLogger: Logger, context: RequestContext) {
  return baseLogger.child({
    requestId: context.requestId,
    correlationId: context.correlationId,
    method: context.method,
    url: context.url,
    userId: context.userId,
    ip: context.ip,
  });
}

export function createLogger(config: LoggerConfig = {}): Logger {
  const serviceName = config.serviceName ?? 'app';
  const options: LoggerOptions = {
    level: config.level ?? process.env.LOG_LEVEL ?? 'info',
    base: { service: serviceName },
  };

  if (process.env.NODE_ENV === 'production' || config.logDir) {
    const destination = createRotatingDestination(
      config.logDir ?? 'logs',
      serviceName,
      config.maxSize ?? '10m',
      config.maxFiles ?? 7,
    );
    return pino(options, destination);
  }

  return pino(options);
}

import { Request, Response, NextFunction } from 'express';
import jwt, { JwtPayload } from 'jsonwebtoken';
import { AppError } from '../middleware/error';
import { AuthToken } from '../types';

interface AuthJwtPayload extends JwtPayload {
  userId: string;
  role?: string;
}

const extractToken = (authorization?: string): string | null => {
  if (!authorization) return null;
  const [scheme, token] = authorization.split(' ');
  if (!scheme || scheme.toLowerCase() !== 'bearer' || !token) return null;
  return token.trim();
};

export const authenticate = (req: Request, _res: Response, next: NextFunction) => {
  try {
    const token = extractToken(req.headers.authorization);

    if (!token) {
      throw new AppError('Authentication token is required', 401, 'AUTH_TOKEN_MISSING');
    }

    const secret = process.env.JWT_SECRET;
    if (!secret) {
      throw new AppError('Authentication service is unavailable', 500, 'AUTH_SECRET_MISSING');
    }

    const decoded = jwt.verify(token, secret);
    if (typeof decoded === 'string' || !decoded || typeof decoded !== 'object') {
      throw new AppError('Invalid authentication token', 401, 'AUTH_TOKEN_INVALID');
    }

    const payload = decoded as AuthJwtPayload;
    if (typeof payload.userId !== 'string' || payload.userId.length === 0) {
      throw new AppError('Invalid authentication token payload', 401, 'AUTH_TOKEN_INVALID');
    }

    req.user = {
      id: payload.userId,
      role: payload.role ?? 'user',
    } as AuthToken;

    next();
  } catch (error) {
    if (error instanceof AppError) {
      return next(error);
    }
    return next(new AppError('Invalid or expired authentication token', 401, 'AUTH_TOKEN_INVALID'));
  }
};

export const requireRole = (...roles: string[]) => {
  return (req: Request, _res: Response, next: NextFunction) => {
    const userRole = req.user?.role;

    if (!userRole) {
      return next(new AppError('Authentication required', 401, 'AUTH_REQUIRED'));
    }

    if (!roles.includes(userRole)) {
      return next(new AppError('Insufficient permissions', 403, 'FORBIDDEN'));
    }

    next();
  };
};
